#!/bin/sh
# Usage: scripts/find-bool-exports.sh [DIR]   (needs ripgrep)
# A heuristic, not a parser. Lists Rust functions and function-pointer types with a
# C-family ABI that return bool, including signatures split over several lines. Calls
# into C declared inside an `extern "C" { ... }` block are not listed: they are compiled
# by the C compiler.
# Known misses: raw identifiers (fn r#name), parameters nested more than one bracket
# deep (such as a callback that itself takes a callback), functions generated by
# macros, and bool behind a type alias. It also matches signatures inside comments.
# No match does not mean a library is safe.
d=${1:-.}
[ -e "$d" ] || { echo "$d: no such file or directory" >&2; exit 2; }
rg --type rust -nU --no-heading \
  -e '\bextern\s+(?:"(?:C|system|sysv64)(?:-unwind)?"\s+)?fn\s*\w*\s*(?:<[^>{]*>)?\s*\((?:[^()]|\([^()]*\))*\)\s*->\s*bool\b' \
  -- "$d"
rc=$?
[ $rc -eq 1 ] && echo "no matches in $d (see the known misses above)" >&2
exit $rc
